using System;
using System.Collections.Generic;

public static int[] Dijkstra(List<(int node, int weight)>[] graph, int start, int V) {
    int[] dist = new int[V];
    bool[] visited = new bool[V];

    for (int i = 0; i < V; i++)
        dist[i] = int.MaxValue;
    dist[start] = 0;

    var pq = new SortedSet<(int distance, int node)>();
    pq.Add((0, start));

    while (pq.Count > 0) {
        var (d, u) = pq.Min;
        pq.Remove(pq.Min);

        if (visited[u]) continue;
        visited[u] = true;

        foreach (var (v, w) in graph[u]) {
            if (dist[u] + w < dist[v]) {
                pq.Remove((dist[v], v));
                dist[v] = dist[u] + w;
                pq.Add((dist[v], v));
            }
        }
    }
    return dist;
}
